usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Projects.Update(
		context.TODO(),
		"project_id",
		openai.AdminOrganizationProjectUpdateParams{
			Name: param.NewOpt[string]("string"),
			ExternalKeyID: param.NewOpt[string]("string"),
			Geography: param.NewOpt[string]("string"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
